<?php

declare(strict_types=1);

namespace Raneomik\NettePWA\Push;

use Minishlink\WebPush\WebPush;

/**
 * Generated by Nette DI (PWALatteExtension): a new WebPush per send. WebPush keeps a queue that
 * only flush() empties; a shared instance would carry it over to the next request in worker mode.
 */
interface WebPushFactory
{
    public function create(): WebPush;
}
